const { IRISIterator } = require('./iris_iterator.js')
const {_point} = require('./_point.js')

class IRISGlobalNode {

  constructor (iris, globalName, ...subscripts) {
    this._iris = iris
    this._global_name = globalName
    this._subscripts = subscripts
    this._start = _point.BEFOREFIRST()
    this._stop = _point.AFTERLAST()
    this._reversed = false
    this._size = undefined
  }

  [Symbol.iterator] () {
    return this.entries()
  }

  clear () {
    this._iris.kill(this._global_name)
    this._size = 0
    return undefined
  }

  delete (subscript) {
    const existed = this.has(subscript)
    this._iris.kill(this._global_name, ...this._subscripts, subscript)
    if (existed) this._size -= 1
    return existed
  }

  entries () {
    return new IRISIterator(this, IRISIterator.VIEW.ITEMS)
  }

  forEach (callback, thisArg = undefined) {
    callback = callback.bind(thisArg)
    let pair
    for (pair of this.entries()) {
      callback(...pair, this)
    }
  }

  // If the value that is associated 
  //  * to the provided subscript is an object, then you will get a reference to that object
  //  * and any change made to that object will effectively modify it inside the Map object.
  // This is the description of the get Map function. This class does not implement these requirements (GD: Feb 25)
  
  get (subscript, default_value = undefined) {
    let iris_value = undefined 
    if (this.has(subscript)) {
      // get will return null both for undefined nodes AND for empty string.
      // this check is required so that we can returned undefined (as a JS Map would) for 
      // undefined subscripts
      iris_value = this._iris.get(this._global_name, ...this._subscripts, subscript)
    }
    return (iris_value !== undefined) ? iris_value : default_value
  }

  has (subscript) {
    return this._iris.isDefined(this._global_name, ...this._subscripts, subscript) != 0
  }

  keys () {
    return new IRISIterator(this, IRISIterator.VIEW.SUBSCRIPTS)
  }

  subscripts () {
    return this.keys()
  }

  set (subscript, value) {
    this._iris.set(value, this._global_name, ...this._subscripts, subscript)
    // lazy update: the following will force recomputation next time we check the size property
    // but it avoids a second call (for isDefined) to IRIS
    this._size = undefined
    return this
  }

  values () {
    return new IRISIterator(this, IRISIterator.VIEW.VALUES)
  }

  nodeEntries () {
    return new IRISIterator(this, IRISIterator.VIEW.NODEITEMS)
  } 

  nodes () {
    return new IRISIterator(this, IRISIterator.VIEW.NODES)
  }

  reversed () {
    const newnode = new IRISGlobalNode(this._iris, this._global_name, ...this._subscripts)
    newnode._reversed = !this._reversed
    newnode._start = this._stop
    newnode._stop = this._start
    return newnode[Symbol.iterator]()
  }

  node (subscript) {
    return this._iris.node(this._global_name, ...this._subscripts, subscript)
  }

  get size () {
    return this._computeSize()
  }

  get [Symbol.toStringTag] () {
    return 'IRISGlobalNode'
  }

  /**
   * Returns a helper point to be used during iteration. Points act like markers for
   * the start and the end of the iteration as well as moving cursors.
   * @param {*} key the current subscript
   * @param {boolean} inclusive whether it should be included or not in the output
   * @returns a new [_point]{@link module:"intersystems-iris"._point}
   * @memberof module:"intersystems-iris".IRISGlobalNode
   */
  static _point (key, inclusive = undefined) {
    return new _point(key, inclusive)
  }

  /**
   * Returns the min subscript - X or Y - that we can use as a stop 
   * @function _minStop
   * @param {*} X a candidate subscript
   * @param {*} Y a candidate subscript
   * @returns X if X < Y and Y otherwise
   * @memberof module:"intersystems-iris".IRISGlobalNode
   */
  _minStop (X, Y) {
    const sortOrder = _point._sortOrder(this._iris, this._global_name, X, Y)
    if (sortOrder > 0) return this._reversed ? Y : X
    else if (sortOrder < 0) return  this._reversed ? X : Y
    else return (X._inclusive || X._inclusive == Y._inclusive) ? Y : X
  }
  
  /**
   * Returns the max subscript - X or Y - that we can use as a start
   * @function _maxStart
   * @param {*} X a candidate subscript
   * @param {*} Y a candidate subscript
   * @returns X if X > Y and Y otherwise
   * @memberof module:"intersystems-iris".IRISGlobalNode
   */
  _maxStart (X, Y) {
    const sortOrder = _point._sortOrder(this._iris, this._global_name, X, Y)
    if (sortOrder > 0) return this._reversed ? X : Y
    else if (sortOrder < 0) return  this._reversed ? Y : X
    else return (X._inclusive || X._inclusive == Y._inclusive) ? Y : X
  }  

  /**
   * This is an internal method intended to be used for debugging purposes only.
   * Returns a formatted string that describes the state of slicing in the IRISGlobalNode object.
   * IRISGlobalNode object can be sliced to limit the subscript traversing range.
   * node.slice(start,end). This results in a new IRISGlobalNode object with the subsript 
   * range limited to from start (inclusive) to stop (exclusive). The only way to traverse the node
   * using a slice is the forward direction. The formatted string uses the standard mathematical 
   * notation of bracketing. Square brackets, [], are used to denote closed intervals with 
   * inclusive endpoints. Parentheses, (), are used to denote open intervals with exclusive 
   * endpoints. For example, "[ 3 >>> 7 )" means from 3 to 7, forward direction, inclusive of 3 
   * but exclusive of 7. This is what you will get with a simple slicing of node[3:7]
   * @function _sliceState
   * @returns A string representation of the slice state
   * @memberof module:"intersystems-iris".IRISGlobalNode
   */ 
  _sliceState () {
    let leftBracket = ''
    let leftKey = ''
    let arrows = ''
    let rightKey = ''
    let rightBracket = ''

    leftBracket = this._start._inclusive ? '[ ' : '( '
    leftKey = this._start.marksFirst() ? 'undefined' : ('\'' + this._start._key.replace('\'', '\\\'') + '\'')
    arrows = ' >>> '
    rightKey = this._stop.marksLast() ? 'undefined' : ('\'' + this._stop._key.replace('\'', '\\\'') + '\'')
    rightBracket = this._stop._inclusive ? ' ]' : ' )'

    return leftBracket + leftKey + arrows + rightKey + rightBracket
  }

  // *generate (view, startFrom = undefined) {
  //   let moveTo = startFrom
  //   let iterator = (new IRISIterator(this, view)).startFrom(moveTo)
  //   let value
  //   for (value of iterator) {
  //     moveTo = yield value
  //     if (startFrom) {
  //       iterator = iterator.startFrom(moveTo)
  //     }
  //   }
  // }

  _computeSize () {
    if (!this._size) {
      this._size = 0
      let value
      for (value of this.values()) {
        this._size += 1
        value // no-unused-vars
      }
    }
    return this._size
  }
 
}

module.exports.IRISGlobalNode = IRISGlobalNode
